130	// A replacement is either LITERAL (`{ from, to }`) or a PATTERN
131	// (`{ pattern: /…/g, to }`) — the regex-first shape engine migrations are meant to
132	// take (DESIGN §2.3), for the changes where no literal is common across repos.
133	// The pattern must be global, because every replacement here means replace-ALL:
134	// a non-global regex would silently rewrite only the first occurrence and leave a
135	// half-migrated file that reads as migrated.
136	export async function applyRewrites(migration, { read, write, env = process.env }) {
137	  if (!migration.rewrite?.length) return [];
138	  if (migration.appliesTo && !(await migration.appliesTo(read))) return [];
139	  const done = [];
140	  for (const { file, replace } of migration.rewrite) {
141	    const text = await read(file);
142	    if (text == null) continue;
143	    // The same gate `applyMaterializations` applies above, for the same reason and on
144	    // the same surface: a rewrite naming a path under `.github/workflows/` is a workflow
145	    // delivery too. It went unguarded until #1509 because no record rewrote one — and an
146	    // unguarded rewrite is worse than an unguarded materialization, because the caller's
147	    // `write` drops the path silently while `done` still names the file, so a run that
148	    // delivered nothing reported that it had.
149	    if (file.startsWith(WORKFLOW_DEST) && !callerCanDeliverWorkflows(env)) {
150	      done.push(`SKIPPED ${file} (workflow file; this caller cannot deliver one)`);
151	      continue;
152	    }
153	    let next = text;
154	    for (const r of replace ?? []) {
155	      if (r.pattern !== undefined) {
156	        if (!(r.pattern instanceof RegExp) || !r.pattern.global) {
157	          throw new Error(`migration ${migration.id}: rewrite pattern for ${file} must be a global RegExp — a non-global one rewrites only the first match`);
158	        }
159	        next = next.replace(r.pattern, r.to);
